// ReportMeasuredLatencyMs reports the arithmetic mean of actual observations.
func ReportMeasuredLatencyMs(observed []float64) float64 {
	if len(observed) == 0 { return 0 }
	var total float64
	for _, value := range observed { total += value }
	return total / float64(len(observed))
}

